/* One learner identity and account, independent course registrations. */
let learnerProfiles=[],learnerListMode='active';
const learnerKey=s=>s.profile_id||s.national_id||s.id;
const activeClasses=()=>db.students.filter(s=>!s.archived_at);
const learnerGroups=list=>Array.from(list.reduce((map,s)=>{const key=learnerKey(s);if(!map.has(key))map.set(key,[]);map.get(key).push(s);return map},new Map()).values());
const classesFor=s=>db.students.filter(c=>learnerKey(c)===learnerKey(s));
const classLabel=s=>`${s.subject||'کلاس'} · استاد ${teacher(s.teacher_id)} · ${days[s.weekday]} ${s.class_time?.slice(0,5)||''}`;
const reloadBeforeClasses=reload;
reload=async function(){learnerProfiles=role!=='teacher'?await api('/rest/v1/learner_profiles?select=*&order=created_at'):[];return reloadBeforeClasses()};
const eligibleBeforeClasses=eligible;eligible=s=>!s.archived_at&&eligibleBeforeClasses(s);
studentTable=function(list){return table(['هنرجو','کلاس‌ها و استادها','شهریه و وضعیت','پرونده'],learnerGroups(list).map(courses=>{const s=courses[0];return `<tr><td><b>${esc(full(s))}</b><small class="sub">${esc(s.mobile||'')}</small><small class="sub">${money(courses.length)} کلاس${s.archived_at?' · حذف‌شده':''}</small></td><td>${courses.map(c=>`<div class="learner-table-class"><strong>${esc(c.subject)}</strong><span>${esc(teacher(c.teacher_id))} · ${days[c.weekday]} ${esc(c.class_time?.slice(0,5))}</span></div>`).join('')}</td><td>${courses.map(c=>`<div class="learner-table-class"><span>${esc(c.subject)} · ${money(credit(c))} جلسه</span><span>${money(remainingDebt(c))} تومان بدهی</span>${c.archived_at?'<span class="badge red">حذف‌شده از فعال‌ها</span>':tag(c)}</div>`).join('')}</td><td><button onclick="studentDetail('${s.id}')">مشاهده پرونده</button></td></tr>`}))};
views.students=function(){return title('هنرجویان','یک پرونده برای هر هنرجو؛ استاد و شهریهٔ مستقل برای هر کلاس',btn('هنرجوی جدید','newStudent()'))+`<div class="card"><div class="learner-toolbar"><div class="learner-tabs"><button class="${learnerListMode==='active'?'primary':''}" onclick="setLearnerMode('active')">فعال‌ها · ${money(learnerGroups(activeClasses()).length)}</button>${admin?`<button class="${learnerListMode==='archived'?'primary':''}" onclick="setLearnerMode('archived')">حذف‌شده‌ها · ${money(learnerGroups(db.students.filter(s=>s.archived_at)).length)}</button>`:''}</div><input type="search" placeholder="نام، کد ملی، شماره یا استاد…" oninput="filterStudents(this.value)"></div><div id="studentlist">${studentTable(db.students.filter(s=>learnerListMode==='archived'?s.archived_at:!s.archived_at))}</div></div>`};
function setLearnerMode(mode){learnerListMode=mode==='archived'&&admin?'archived':'active';render()}
filterStudents=function(q){const term=digits(q).trim().toLowerCase(),list=db.students.filter(s=>learnerListMode==='archived'?s.archived_at:!s.archived_at);$('studentlist').innerHTML=studentTable(learnerGroups(list).filter(g=>g.some(s=>digits(full(s)+' '+(s.national_id||'')+' '+(s.mobile||'')+' '+classLabel(s)).toLowerCase().includes(term))).flat())};
function classCard(s,manage=false){return `<article class="learner-class-card"><div class="learner-class-heading"><div><h3>${esc(s.subject)}</h3><p>${esc(teacher(s.teacher_id))} · ${days[s.weekday]} · ${esc(s.class_time?.slice(0,5))}</p></div>${s.archived_at?'<span class="badge red">غیرفعال</span>':tag(s)}</div><div class="class-finances">${[['پرداخت تأییدشده',money(totalPaid(s))+' تومان'],['بدهی باقی‌مانده',money(remainingDebt(s))+' تومان'],['اعتبار همین کلاس',money(credit(s))+' جلسه']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div>${manage&&admin&&!s.archived_at?`<button onclick="editMonth('${s.id}')">تنظیم شهریهٔ این کلاس</button>`:''}${tuitionGrid(monthRows.filter(t=>t.student_id===s.id))}</article>`}
studentDetail=function(id){if(!office)return;const s=db.students.find(c=>c.id===id);if(!s)return;const courses=classesFor(s),profile=learnerProfiles.find(p=>p.id===s.profile_id);
 form('پروندهٔ '+full(s),[],async()=>{});
 $('fields').innerHTML=`<section class="enrollment-summary"><div class="review-person"><div><small>یک حساب · ${money(courses.length)} کلاس</small><h3>${esc(full(s))}</h3></div>${s.archived_at?'<span class="badge red">حذف‌شده از فهرست فعال</span>':''}</div><dl>${[['کد ملی',s.national_id],['موبایل',s.mobile],['نام پدر',s.father_name],['تاریخ تولد',s.birth_date?AcademyDates.show(s.birth_date):'—'],['تلفن منزل',s.home_phone],['نشانی',s.address]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="sub">${s.user_id?'همهٔ کلاس‌ها با همان حساب هنرجو دیده می‌شوند.':'حساب هنرجو هنوز متصل نیست؛ کلاس‌ها در همین پرونده نگهداری می‌شوند.'}</p>${profile?.archived_at?`<p class="archive-reason"><b>دلیل حذف:</b> ${esc(profile.archive_reason)}<br><small>${new Date(profile.archived_at).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'})}</small></p>`:''}<div class="learner-actions">${admin?(s.archived_at?`<button onclick="archiveLearner('${s.id}',true)">بازیابی هنرجو</button>`:`<button class="primary" onclick="addLearnerClass('${s.id}')">＋ افزودن کلاس با استاد دیگر</button><button class="danger-outline" onclick="archiveLearner('${s.id}')">حذف هنرجو با دلیل</button>`):''}</div></section><div class="learner-class-list">${courses.map(c=>classCard(c,true)).join('')}</div>`;
 $('form').querySelector('[type=submit]').textContent='بستن پرونده';$('form').onsubmit=e=>{e.preventDefault();modal.close()};
};
function addLearnerClass(id){if(!admin)return;const s=db.students.find(c=>c.id===id);if(!s||s.archived_at)return;
 form('افزودن کلاس برای '+full(s),[field('teacher_id','استاد کلاس جدید','text',db.teachers.map(t=>[t.id,t.name])),field('subject','رشتهٔ کلاس جدید','text',[]),field('weekday','روز کلاس','text',days.map((d,i)=>[i,d])),field('class_time','ساعت کلاس؛ ۲۰ دقیقه','text',timeOptions),...tuitionFields()],async d=>{await api('/rest/v1/rpc/learner_action','POST',{op:'add_class',data:{student_id:id,teacher_id:d.teacher_id,subject:d.subject,weekday:Number(d.weekday),class_time:d.class_time,month_key:d.month_key,paid:[1,2,3,4].map(i=>d['p'+i]==='true'),note:d.note}})});
 const f=$('form'),other=db.teachers.find(t=>!classesFor(s).some(c=>c.teacher_id===t.id));if(other)f.elements.teacher_id.value=other.id;
 const subjects=()=>{f.elements.subject.innerHTML=(db.teachers.find(t=>t.id===f.elements.teacher_id.value)?.subjects||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')};f.elements.teacher_id.onchange=subjects;subjects();f.elements.class_time.value='17:00';f.elements.month_key.value=defaultMonth()||'';groupTuitionFields();
 const info=document.createElement('p');info.className='class-form-help';info.textContent='حساب هنرجو مشترک است؛ شهریه و حضور این کلاس جدا ثبت می‌شود. هیچ مانده‌ای از کلاس قبلی کپی نمی‌شود.';$('fields').prepend(info);
 const dates=()=>{const values=tuitionDates(f.elements.month_key.value,f.elements.weekday.value);[1,2,3,4].forEach(i=>{const label=f.elements['p'+i].parentElement;let small=label.querySelector('small');if(!small){small=document.createElement('small');label.append(small)}small.textContent=values[i-1]?AcademyDates.show(values[i-1]):''})};f.elements.month_key.onchange=dates;f.elements.weekday.onchange=dates;dates();f.querySelector('[type=submit]').textContent='ثبت کلاس و شهریهٔ مستقل';
}
function archiveLearner(id,restore=false){if(!admin)return;const s=db.students.find(c=>c.id===id);if(!s)return;
 form(restore?'بازیابی '+full(s):'حذف '+full(s)+' از فهرست فعال',[field('reason',restore?'دلیل بازیابی':'دلیل حذف؛ الزامی')],async d=>{if(d.reason.trim().length<3)throw Error('دلیل را حداقل در ۳ حرف وارد کنید');await api('/rest/v1/rpc/learner_action','POST',{op:restore?'restore':'archive',data:{student_id:id,reason:d.reason.trim()}});learnerListMode=restore?'active':'archived'});
 const f=$('form'),area=document.createElement('textarea');area.name='reason';area.required=true;area.minLength=3;area.maxLength=1000;area.rows=3;f.elements.reason.replaceWith(area);
 const info=document.createElement('p');info.className='class-form-help';info.textContent=restore?'همهٔ کلاس‌های هنرجو بازیابی می‌شوند؛ اگر زمان‌ها اشغال شده باشند، بازیابی انجام نمی‌شود.':`${money(classesFor(s).length)} کلاس از فهرست فعال کنار می‌رود. سوابق شهریه، رسیدها، حضور و دستمزد پاک نمی‌شوند. دلیل و حساب مدیر در گزارش ثبت می‌شود.`;$('fields').prepend(info);
 const button=f.querySelector('[type=submit]');button.textContent=restore?'بازیابی هنرجو':'ثبت دلیل و حذف از فعال‌ها';if(!restore)button.classList.add('archive-submit');area.focus();
}
const portalBeforeClasses=views.portal;
views.portal=function(){const courses=db.students.filter(s=>s.user_id===uid);if(!courses.length)return portalBeforeClasses();return title('کلاس‌های من','هر کلاس، برنامه و شهریهٔ جدا دارد')+`<div class="hero"><div><h2>${esc(full(courses[0]))}</h2><p>${money(courses.filter(c=>!c.archived_at).length)} کلاس فعال · یک حساب هنرجو</p></div></div><div class="learner-class-list">${courses.map(c=>classCard(c)).join('')}</div><div class="card"><h3>اطلاعیه‌ها</h3>${db.notices.map(n=>`<p>${esc(n.message)}</p>`).join('')||'<p>اطلاعیه‌ای ثبت نشده است.</p>'}<button onclick="go('monthly')">شهریه و رسیدهای من</button></div>`};
render();
